input.command:
cd /workspace/work
timeout 60 duckdb analysis.duckdb -c "$(cat /workspace/sql/load.sql)
CREATE OR REPLACE TABLE input_list AS
SELECT row_number() OVER () AS row_num, cod_imovel, municipio, cod_estado, geometry AS geom_wkt
FROM read_csv('/workspace/lists/goias-sample.csv', header=true, all_varchar=true);

-- duplicate check among id rows
SELECT cod_imovel, count(*) c FROM input_list WHERE cod_imovel IS NOT NULL GROUP BY cod_imovel HAVING count(*)>1;

SELECT row_num, cod_imovel, municipio, cod_estado, geom_wkt FROM input_list WHERE cod_imovel IS NULL;
"

cd /workspace/work
cat > /workspace/sql/13_envelope.sql << 'EOF'
LOAD httpfs; LOAD spatial; SET geometry_always_xy = true;

CREATE OR REPLACE TABLE envelope_box AS
SELECT min(ST_XMin(geometry)) xmin, min(ST_YMin(geometry)) ymin,
       max(ST_XMax(geometry)) xmax, max(ST_YMax(geometry)) ymax
FROM resolved_parcels;

SELECT * FROM envelope_box;
EOF
timeout 60 duckdb analysis.duckdb < /workspace/sql/13_envelope.sql

cd /workspace/work
cat > /workspace/sql/14_buffered_union.sql << 'EOF'
LOAD httpfs; LOAD spatial; SET geometry_always_xy = true;

CREATE OR REPLACE TABLE resolved_parcels_5880 AS
SELECT cod_imovel, ST_Transform(geometry, 'EPSG:4326','EPSG:5880', always_xy:=true) AS geom_5880
FROM resolved_parcels;

CREATE OR REPLACE TABLE resolved_parcels_buffered AS
SELECT cod_imovel, ST_Buffer(geom_5880, 25.0) AS geom_buf_5880
FROM resolved_parcels_5880;

CREATE OR REPLACE TABLE buffered_union_5880 AS
SELECT ST_Union_Agg(geom_buf_5880) AS geom FROM resolved_parcels_buffered;

CREATE OR REPLACE TABLE buffered_union_4326 AS
SELECT ST_Transform(geom, 'EPSG:5880','EPSG:4326', always_xy:=true) AS geom FROM buffered_union_5880;

SELECT ST_Area(geom) FROM buffered_union_4326;
EOF
time timeout 300 duckdb analysis.duckdb < /workspace/sql/14_buffered_union.sql

cd /workspace/work
cat > /workspace/sql/22_routing.sql << 'EOF'
LOAD httpfs; LOAD spatial; SET geometry_always_xy = true;

CREATE OR REPLACE TABLE routing_table (mbmode24 INTEGER, tiers VARCHAR);
INSERT INTO routing_table VALUES
(15,'slaughter_point'),
(21,'slaughter_point'),
(20,'mill_point'),
(39,'intake_point'),
(41,'intake_point'),
(18,'intake_point|mill_point'),
(35,'none'),
(46,'none');

CREATE OR REPLACE TABLE parcel_dominant_class AS
WITH agg AS (
  SELECT cod_imovel, mbmode24, sum(field_area_ha) AS ha
  FROM matched_fields_full
  GROUP BY cod_imovel, mbmode24
),
ranked AS (
  SELECT *, row_number() OVER (PARTITION BY cod_imovel ORDER BY ha DESC, mbmode24 ASC) AS rn
  FROM agg
)
SELECT cod_imovel, mbmode24 AS dominant_mb FROM ranked WHERE rn=1;

SELECT count(*) FROM parcel_dominant_class;
SELECT dominant_mb, count(*) FROM parcel_dominant_class GROUP BY dominant_mb ORDER BY dominant_mb;

CREATE OR REPLACE TABLE flagged_parcels AS
SELECT DISTINCT cod_imovel FROM matched_fields_scoped WHERE in_scope AND era5_ha > 0;
SELECT count(*) FROM flagged_parcels;
EOF
timeout 60 duckdb analysis.duckdb < /workspace/sql/22_routing.sql

