input.command:
cd /workspace/work
cat > /workspace/sql/28_q27.sql << 'EOF'
LOAD httpfs; LOAD spatial; SET geometry_always_xy = true;

CREATE OR REPLACE TABLE flagged_muni AS
SELECT fc.cod_imovel, m.cod_ibge, m.municipio_nome
FROM flagged_centroids fc
JOIN br_muni m ON ST_Within(fc.centroid_4326, m.geometry);

SELECT count(*) FROM flagged_muni;

CREATE OR REPLACE TABLE q27_result AS
SELECT fm.cod_imovel, fl.entity_id, fl.weight AS evidence
FROM flagged_muni fm
JOIN facilities_local fl ON fl.tier='membership_muni' AND fl.entity_id = fm.cod_ibge;

SELECT * FROM q27_result ORDER BY cod_imovel;
EOF
timeout 60 duckdb analysis.duckdb < /workspace/sql/28_q27.sql

cd /workspace/work
cat > /workspace/sql/28b_q27_fixed.sql << 'EOF'
LOAD httpfs; LOAD spatial; SET geometry_always_xy = true;

CREATE OR REPLACE TABLE flagged_muni AS
SELECT cod_imovel, split_part(cod_imovel,'-',2) AS cod_ibge
FROM flagged_parcels;

CREATE OR REPLACE TABLE q27_result AS
SELECT fm.cod_imovel, fl.entity_id, fl.weight AS evidence
FROM flagged_muni fm
JOIN facilities_local fl ON fl.tier='membership_muni' AND fl.entity_id = fm.cod_ibge;

SELECT count(*) FROM q27_result;
SELECT * FROM q27_result ORDER BY cod_imovel;
